create table league_invites (id uuid primary key default gen_random_uuid(),league_id uuid not null references fantasy_leagues(id) on delete cascade,invited_by uuid not null references auth.users(id),email text,invite_token uuid not null default gen_random_uuid() unique,status text not null default 'pending' check(status in('pending','accepted','revoked','expired')),expires_at timestamptz not null default(now()+interval '14 days'),accepted_by uuid references auth.users(id),accepted_at timestamptz,created_at timestamptz not null default now());
