alter table user_profiles enable row level security; alter table league_invites enable row level security; alter table drafts enable row level security; alter table draft_picks enable row level security; alter table trades enable row level security; alter table trade_items enable row level security; alter table trade_messages enable row level security; alter table achievements enable row level security; alter table franchise_achievements enable row level security; alter table stadiums enable row level security; alter table stadium_features enable row level security; alter table franchise_stadium_features enable row level security;
create policy profile_read_authenticated on user_profiles for select to authenticated using(true); create policy profile_manage_self on user_profiles for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy member_read_drafts on drafts for select to authenticated using(exists(select 1 from league_seasons ls where ls.id=league_season_id and public.is_league_member(ls.league_id))); create policy member_read_draft_picks on draft_picks for select to authenticated using(exists(select 1 from drafts d join league_seasons ls on ls.id=d.league_season_id where d.id=draft_id and public.is_league_member(ls.league_id)));
create policy member_read_trades on trades for select to authenticated using(exists(select 1 from league_seasons ls where ls.id=league_season_id and public.is_league_member(ls.league_id))); create policy member_read_trade_items on trade_items for select to authenticated using(exists(select 1 from trades t join league_seasons ls on ls.id=t.league_season_id where t.id=trade_id and public.is_league_member(ls.league_id)));
create policy trade_participant_read_messages on trade_messages for select to authenticated using(exists(select 1 from trades t join season_franchises a on a.id=t.proposed_by_franchise_id join season_franchises b on b.id=t.proposed_to_franchise_id join franchise_owners fa on fa.franchise_id=a.franchise_id join franchise_owners fb on fb.franchise_id=b.franchise_id where t.id=trade_id and ((fa.user_id=auth.uid() and fa.ends_on is null) or (fb.user_id=auth.uid() and fb.ends_on is null))));
create policy authenticated_read_achievements on achievements for select to authenticated using(true); create policy authenticated_read_stadium_features on stadium_features for select to authenticated using(true); create policy member_read_franchise_achievements on franchise_achievements for select to authenticated using(exists(select 1 from franchises f where f.id=franchise_id and public.is_league_member(f.league_id))); create policy member_read_stadiums on stadiums for select to authenticated using(exists(select 1 from franchises f where f.id=franchise_id and public.is_league_member(f.league_id))); create policy member_read_franchise_stadium_features on franchise_stadium_features for select to authenticated using(exists(select 1 from stadiums s join franchises f on f.id=s.franchise_id where s.id=stadium_id and public.is_league_member(f.league_id)));
insert into achievements(code,display_name,description,category) values('FIRST_WIN','First Win','Win the first matchup in franchise history.','milestone'),('RIVALRY_WIN','Rivalry Win','Win a Rivalry Week matchup.','rivalry'),('REVENGE_COMPLETE','Revenge Complete','Win a designated Revenge Week rematch.','revenge'),('LEAGUE_CHAMPION','League Champion','Win the league championship.','championship'),('GIANT_KILLER','Giant Killer','Defeat a substantially higher-ranked franchise during a qualifying event.','weekly') on conflict(code) do nothing;
